#!/usr/bin/env python3
"""One-off generator for data/content.json (stable ids). After that, content.json is the source of truth:
edit/delete items there, then run scripts/sync-fallback.py to refresh js/content-fallback.js."""
import json,sys
old=json.load(open(sys.argv[1]))
items=[]
def add(prefix,typ,texts):
    for i,t in enumerate(texts,1):
        items.append({"id":"%s-%03d"%(prefix,i),"type":typ,"text":t} if isinstance(t,str) else dict({"id":"%s-%03d"%(prefix,i),"type":typ},**t))
